def font(r,size=14,bold=False,italic=False):
    r.font.name='Times New Roman';r.font.size=Pt(size);r.bold=bold;r.italic=italic;r.font.color.rgb=RGBColor(0,0,0)
    rf=r._element.get_or_add_rPr().rFonts
    for a in ['ascii','hAnsi','eastAsia','cs']:rf.set(qn('w:'+a),'Times New Roman')

def field(p,instruction,value):
    el=OxmlElement('w:fldSimple');el.set(qn('w:instr'),instruction)
    r=OxmlElement('w:r');rp=OxmlElement('w:rPr');rf=OxmlElement('w:rFonts')
    for a in ['ascii','hAnsi','eastAsia','cs']:rf.set(qn('w:'+a),'Times New Roman')
    sz=OxmlElement('w:sz');sz.set(qn('w:val'),'24' if instruction.strip()=='PAGE' else '28');rp.extend([rf,sz]);r.append(rp)
    t=OxmlElement('w:t');t.text=str(value);r.append(t);el.append(r);p._p.append(el)

def placeholder(n,desc):
    f=BASE/f'placeholder_{n:02d}.png';im=PILImage.new('RGB',(1320,520),'#f7f7f7');dr=ImageDraw.Draw(im)
    dr.rectangle((2,2,1317,517),outline='#cccccc',width=3)
    ft=ImageFont.truetype('C:/Windows/Fonts/times.ttf',38);small=ImageFont.truetype('C:/Windows/Fonts/times.ttf',29)
    dr.text((660,110),f'ВСТАВИТЬ СКРИНШОТ {n}',font=ft,fill='#333333',anchor='mm')
    words=desc.split();lines=[];line=''
    for w in words:
        if dr.textlength(line+' '+w,font=small)>1150:lines.append(line);line=w
        else:line=(line+' '+w).strip()
    if line:lines.append(line)
    for j,line in enumerate(lines):dr.text((660,195+j*40),line,font=small,fill='#555555',anchor='mm')
    dr.text((660,440),'Удалить эту заглушку и вставить снимок из своей базы 1С',font=small,fill='#777777',anchor='mm')
    im.save(f);return f

